/* ---------------- 16. HANDOFF SHEET on compacting (the owner, 2026-09-15) */

// On compacting, the orchestrator's memory is summarized and whatever is not on
// disk is lost. PreCompact writes the sheet from the ledger; SessionStart with
// source=compact gives it back as context. Only the OWNER session; it never blocks;
// with no active program it does not exist.
console.log('\n16. HANDOFF SHEET — PreCompact writes it, SessionStart(compact) injects it');
hardClearState(repo);
loadSkill('orq', 'owner-session-handoff');
const HANDOFF = path.join(repo, '.git', 'orchestrator-handoff.md');
// some state so the sheet has content: an artifact with rounds, a wait, a dispatch
// written and a pending spec
for (let i = 0; i < 3; i++) { fire({ ...agentEvent('lane T7 review'), session_id: 'owner-session-handoff' }); }
fire({ hook_event_name: 'PostToolUse', tool_name: 'Write', cwd: repo, session_id: 'owner-session-handoff',
  tool_input: { file_path: 'splits/BRIEF-T7.md', content: '# T7 — test brief\n' } });
writeMap({ rules: [{ code: ['services/api/approvals/**'], spec: 'docs/specs/approvals.md' }] });
fire({ ...postEvent('Edit', 'services/api/approvals/handoff.js'), session_id: 'owner-session-handoff' });

const pre = fire({ hook_event_name: 'PreCompact', trigger: 'auto', cwd: repo, session_id: 'owner-session-handoff' });
assert('the owner\'s PreCompact: it exits 0 and keeps quiet (it never blocks the compaction)', pre.code === 0 && pre.stdout === '');
assert('  ...and it writes the handoff sheet next to the ledger', fs.existsSync(HANDOFF));
const sheet = fs.existsSync(HANDOFF) ? fs.readFileSync(HANDOFF, 'utf8') : '';
assert('  ...the sheet names the program', new RegExp('program ' + readState(repo).program_id).test(sheet));
assert('  ...the sheet carries the brief that was written, with its absolute path', sheet.includes(path.resolve(repo, 'splits/BRIEF-T7.md')));
assert('  ...the sheet carries the spec demanded and untouched', /docs\/specs\/approvals\.md/.test(sheet));
assert('  ...the sheet carries the artifact with its rounds', /lane t7 review/.test(sheet) && /rounds=/.test(sheet));
assert('  ...and it orders reloading the skill and running status', /Load the `orq` skill again/.test(sheet) && /status/.test(sheet));
assert('  ...and the ledger records that it was written', (readState(repo).handoff || {}).written_at !== undefined);

const after = fire({ hook_event_name: 'SessionStart', source: 'compact', cwd: repo, session_id: 'owner-session-handoff' });
assert('the owner\'s SessionStart(compact): it gives the sheet back as context', after.code === 0 && /HANDOFF SHEET/.test(after.stdout) && /additionalContext/.test(after.stdout));
assert('  ...with the brief inside', after.stdout.includes('BRIEF-T7.md'));
const normalStartup = fire({ hook_event_name: 'SessionStart', source: 'startup', cwd: repo, session_id: 'owner-session-handoff' });
assert('SessionStart(startup) injects NOTHING (there is no thread to pick up)', !/HANDOFF SHEET/.test(normalStartup.stdout));
const laneCompacts = fire({ hook_event_name: 'SessionStart', source: 'compact', cwd: repo, session_id: 'lane-session-T7' });
assert('a LANE that compacts does NOT receive the orchestrator\'s sheet', !/HANDOFF SHEET/.test(laneCompacts.stdout));
fs.rmSync(HANDOFF);
const noFile = fire({ hook_event_name: 'SessionStart', source: 'compact', cwd: repo, session_id: 'owner-session-handoff' });
assert('if PreCompact never got to write it, SessionStart generates it from the ledger just the same', /HANDOFF SHEET/.test(noFile.stdout) && /BRIEF-T7\.md/.test(noFile.stdout));
const byHand = cli(['handoff'], repo);
assert('`handoff` by hand prints the same sheet', byHand.status === 0 && /ORCHESTRATION HANDOFF/.test(byHand.stdout) && /BRIEF-T7\.md/.test(byHand.stdout));
cli(['close', '--even-if-left-open'], repo); // T46: waits left open by rebound from earlier tests in this repo; it is closed on purpose
const preClosed = fire({ hook_event_name: 'PreCompact', trigger: 'manual', cwd: repo, session_id: 'owner-session-handoff' });
assert('with no active program, PreCompact writes nothing (installed is not activated)', preClosed.code === 0 && !fs.existsSync(HANDOFF));
// mutant: without the write, PreCompact stops producing the sheet
loadSkill('orq', 'owner-session-handoff');
const m7 = path.join(root, 'm7.js');
fs.writeFileSync(m7, source.replace("case 'PreCompact':    handlePreCompact(L, p, input);   break;", "case 'PreCompact': break;"));
fire({ hook_event_name: 'PreCompact', trigger: 'auto', cwd: repo, session_id: 'owner-session-handoff' }, m7);
assert('the mutant with no handlePreCompact STOPS writing the sheet', !fs.existsSync(HANDOFF));
fs.rmSync(MAP);
cli(['close', '--even-if-left-open'], repo); // T46: waits left open by rebound from earlier tests in this repo; it is closed on purpose

/* ---------------- 17. LOAD BOARD + gate terminal_load (the owner, 2026-09-15) */

// WHY: "the orchestrator is not keeping track of other sessions' context, and it
// keeps delegating tasks to them instead of sending subagents to work if there are
// no terminals with little context open" (the owner, 09-15).
//
// What is tested here, in this order:
//  (a) the context comes out of the REAL TRANSCRIPT (a JSONL fixture with `usage`),
//      adding input + cache_creation + cache_read, and from the LAST `type:"assistant"`
//      record, not the first;
//  (b) with no transcript (or with an unreadable one / one with no usage) it says
//      `?`, NEVER 0 — a 0 here would mean "that terminal is empty", the exact lie;
//  (c) the PERCENTAGE is always against the million (the model window, which is not
//      configured); what comes out of `autoCompactWindow` is the LOAD CEILING, and
//      without that key there is no ceiling and nothing is warned about;
//  (d) `status` and `load` print the board, sorted by descending %;
//  (e) the gate warns when the OWNER writes a brief whose `Folder:` is that of a
//      session above the CEILING (autoCompactWindow over the million), and KEEPS
//      QUIET below it (negative control);
//  (f) the `Stop` lists the full ones ONCE per session and program;
//  (g) mutants: if I break each check, it STOPS detecting.
console.log('\n17. LOAD BOARD — how much context each terminal has left');

// A fake settings.json. What is READ from there is the LOAD CEILING (the model
// window is fixed: 1,000,000). CLAUDE_CONFIG_DIR is the variable with which Claude
// Code moves its configuration folder, and here it is also what lets this be tested
// without touching the real settings.json.
const loadConf = path.join(root, 'conf-load');
fs.mkdirSync(loadConf, { recursive: true });
fs.writeFileSync(path.join(loadConf, 'settings.json'), JSON.stringify({ autoCompactWindow: 550000 }));
// With no skill config: this section tests the SINGLE CEILING of settings.json,
// which is the behaviour it falls back to when `orchestrator.config.json` is absent.
const ENV_WINDOW = { CLAUDE_CONFIG_DIR: loadConf, ORCH_CONFIG: NO_CONFIG };
const CEILING_TOKENS = 550000;   // autoCompactWindow
const PCT_CEILING = 55;          // ...the same number, expressed over the million

/** A JSONL transcript like the real ones: several lines, and the `usage` in the LAST
 *  `assistant` record. Returns its path. */
const transcript = (name, usage) => {
  const p = path.join(root, `tr-${name}.jsonl`);
  const lines = [
    JSON.stringify({ type: 'summary', summary: 'header' }),
    // an OLD `assistant` with another usage: if the reader took the first instead of
    // the last, this number would give the bug away
    JSON.stringify({ type: 'assistant', message: { usage: { input_tokens: 1, cache_creation_input_tokens: 1, cache_read_input_tokens: 1 } } }),
    JSON.stringify({ type: 'user', message: { role: 'user' } }),
    ...(usage === null ? [] : [JSON.stringify({ type: 'assistant', message: { usage } })]),
  ];
  fs.writeFileSync(p, lines.join('\n') + '\n');
  return p;
};

const loadCli = (args, env = {}) => spawnSync('node', [HOOK, ...args], {
  cwd: repo, encoding: 'utf8', windowsHide: true, timeout: 30000,
  env: { ...process.env, ...ENV_WINDOW, ...env },
});
const fireLoad = (payload, bin = HOOK, env = {}) => fire(payload, bin, { ...ENV_WINDOW, ...env });

// The lanes live INSIDE the repo (or in a worktree of it): that is what makes them
// share the git-common-dir and therefore the same ledger.
const fullDir = path.join(repo, 'lane-full');
const emptyDir = path.join(repo, 'lane-empty');
fs.mkdirSync(fullDir, { recursive: true });
fs.mkdirSync(emptyDir, { recursive: true });

// The shape is the one the orchestrator verified on 09-15 in a real transcript
// ({"input_tokens":32,"cache_creation_input_tokens":2770,"cache_read_input_tokens":583794}).
// The percentage goes ALWAYS against the MILLION (the owner, 09-15): 560,000 is 56 %.
const TOK_FULL = 32 + 2770 + 557198; // 560000 -> 56 % (ABOVE the 55 % ceiling)
const TOK_EMPTY = 5 + 10 + 1000;     // 1015   ->  0 %
// The case the owner measured on 09-15: 403,353 tokens is 40 %, NOT 73 %.
const TOK_ALMOST = 403353;           // 403353 -> 40 % (BELOW the ceiling)

hardClearState(repo);
fireLoad({
  hook_event_name: 'PreToolUse', tool_name: 'Skill', cwd: repo, session_id: 'du1a-owner-load',
  tool_input: { skill: 'orq' },
  transcript_path: transcript('owner', { input_tokens: 10, cache_creation_input_tokens: 100, cache_read_input_tokens: 1000 }),
});
assert('loading the skill already records the OWNER on the board',
  ((readState(repo).sessions || {})['du1a-owner-load'] || {}).role === 'owner');

const laneEvent = (session, cwd, tp) => ({
  hook_event_name: 'PostToolUse', tool_name: 'Bash', cwd, session_id: session,
  tool_input: { command: 'node --version' }, tool_response: 'v22.0.0',
  ...(tp === undefined ? {} : { transcript_path: tp }),
});
fireLoad(laneEvent('le2b-lane-full', fullDir,
  transcript('full', { input_tokens: 32, cache_creation_input_tokens: 2770, cache_read_input_tokens: 557198 })));
fireLoad(laneEvent('va3c-lane-empty', emptyDir,
  transcript('empty', { input_tokens: 5, cache_creation_input_tokens: 10, cache_read_input_tokens: 1000 })));

let S = readState(repo).sessions || {};
assert('(a) the context comes from the transcript: input + cache_creation + cache_read',
  (S['le2b-lane-full'] || {}).context_tokens === TOK_FULL,
  `read ${(S['le2b-lane-full'] || {}).context_tokens}, expected ${TOK_FULL}`);
assert('  ...and from the LAST assistant record, not the first',
  (S['va3c-lane-empty'] || {}).context_tokens === TOK_EMPTY,
  `read ${(S['va3c-lane-empty'] || {}).context_tokens}, expected ${TOK_EMPTY}`);
assert('  ...with the event\'s cwd and the lane role',
  (S['le2b-lane-full'] || {}).role === 'lane' && (S['le2b-lane-full'] || {}).cwd === fullDir);
// The counter is checked BEFORE and AFTER another event: a bare `>= 1` would pass
// just the same with a counter stuck at 1 (Codex, 09-15).
const invBefore = (S['le2b-lane-full'] || {}).invocations;
fireLoad(laneEvent('le2b-lane-full', fullDir,
  transcript('full', { input_tokens: 32, cache_creation_input_tokens: 2770, cache_read_input_tokens: 557198 })));
const afterAnotherEvent = (readState(repo).sessions || {})['le2b-lane-full'] || {};
assert('  ...and it counts invocations (it goes up with every event, it does not stay at 1)',
  invBefore >= 1 && afterAnotherEvent.invocations === invBefore + 1,
  `before ${invBefore}, after ${afterAnotherEvent.invocations}`);
assert('  ...and it keeps first_time and last_time',
  Boolean(afterAnotherEvent.first_time) && Boolean(afterAnotherEvent.last_time) &&
  afterAnotherEvent.first_time === (S['le2b-lane-full'] || {}).first_time);

// (b) what could not be read is `?`, never 0
fireLoad(laneEvent('st4d-no-transcript', emptyDir, undefined));
fireLoad(laneEvent('tf5e-ghost-transcript', emptyDir, path.join(root, 'does-not-exist.jsonl')));
const trNoUsage = path.join(root, 'tr-no-usage.jsonl');
fs.writeFileSync(trNoUsage, JSON.stringify({ type: 'assistant', message: { content: [] } }) + '\n');
fireLoad(laneEvent('su6f-no-usage', emptyDir, trNoUsage));
const trBroken = path.join(root, 'tr-broken.jsonl');
fs.writeFileSync(trBroken, '{this is not json\n{"type":"assistant","message":{"usage":\n');
fireLoad(laneEvent('tr7g-broken-transcript', emptyDir, trBroken));
const trZeros = path.join(root, 'tr-zeros.jsonl');
fs.writeFileSync(trZeros, JSON.stringify({ type: 'assistant', message: { usage: { input_tokens: 0, cache_creation_input_tokens: 0, cache_read_input_tokens: 0 } } }) + '\n');
fireLoad(laneEvent('uc8h-usage-at-zero', emptyDir, trZeros));
// A field that is PRESENT but unreadable invalidates the WHOLE measurement. It used
// to count as 0 and the total came out as 32: a full terminal that looked almost
// empty — the exact false green this gate kills. (Codex, 09-15, high.)
const trBrokenField = path.join(root, 'tr-broken-field.jsonl');
fs.writeFileSync(trBrokenField, JSON.stringify({ type: 'assistant', message: { usage: { input_tokens: 32, cache_read_input_tokens: 'unreadable' } } }) + '\n');
fireLoad(laneEvent('ci9i-unreadable-field', emptyDir, trBrokenField));
const trNegativeField = path.join(root, 'tr-neg-field.jsonl');
fs.writeFileSync(trNegativeField, JSON.stringify({ type: 'assistant', message: { usage: { input_tokens: 32, cache_read_input_tokens: -5 } } }) + '\n');
fireLoad(laneEvent('cn0j-negative-field', emptyDir, trNegativeField));
// A tail with SEVERAL unreadable lines is no good for resurrecting an old, low
// measurement as though it were the current one. (Codex, 09-15, high.)
const trOldPlusBroken = path.join(root, 'tr-old-plus-broken.jsonl');
fs.writeFileSync(trOldPlusBroken,
  JSON.stringify({ type: 'assistant', message: { usage: { input_tokens: 1, cache_creation_input_tokens: 1, cache_read_input_tokens: 1 } } }) + '\n' +
  '{broken one\n{broken two\n');
fireLoad(laneEvent('cf1k-unreliable-tail', emptyDir, trOldPlusBroken));
// An EXPLICIT `null` is not an absence: it is broken data, and it invalidates the
// measurement. It used to count as 0 and {input_tokens:32, cache_read:null} gave 32
// (Codex, 2nd round, high).
const trNullField = path.join(root, 'tr-null-field.jsonl');
fs.writeFileSync(trNullField, JSON.stringify({ type: 'assistant', message: { usage: { input_tokens: 32, cache_read_input_tokens: null } } }) + '\n');
fireLoad(laneEvent('nu7r-null-field', emptyDir, trNullField));
// A `usage` that is PRESENT but is not an object cannot be skipped in order to go
// looking for an old, low measurement behind it (Codex, 2nd round, high).
const trUsageNotObject = path.join(root, 'tr-usage-not-object.jsonl');
fs.writeFileSync(trUsageNotObject,
  JSON.stringify({ type: 'assistant', message: { usage: { input_tokens: 3 } } }) + '\n' +
  JSON.stringify({ type: 'assistant', message: { usage: 'unreadable' } }) + '\n');
fireLoad(laneEvent('uo8s-usage-not-object', emptyDir, trUsageNotObject));
// A broken line with VALID records behind it is not "the turn being written": it is
// a damaged file (Codex, 2nd round, high).
const trBrokenInMiddle = path.join(root, 'tr-broken-in-middle.jsonl');
fs.writeFileSync(trBrokenInMiddle,
  JSON.stringify({ type: 'assistant', message: { usage: { input_tokens: 3 } } }) + '\n' +
  '{broken in the middle\n' +
  JSON.stringify({ type: 'user', message: { role: 'user' } }) + '\n');
fireLoad(laneEvent('rm9t-broken-in-middle', emptyDir, trBrokenInMiddle));

S = readState(repo).sessions || {};
for (const s of ['st4d-no-transcript', 'tf5e-ghost-transcript', 'su6f-no-usage', 'tr7g-broken-transcript',
  'uc8h-usage-at-zero', 'ci9i-unreadable-field', 'cn0j-negative-field', 'cf1k-unreliable-tail',
  'nu7r-null-field', 'uo8s-usage-not-object', 'rm9t-broken-in-middle']) {
  assert(`(b) ${s.slice(5)}: context null (never 0, never a half number)`,
    (S[s] || {}).context_tokens === null, `it is ${JSON.stringify((S[s] || {}).context_tokens)}`);
}

// POSITIVE CONTROL of the tolerance: ONE single half-written line at the end is the
// turn being written, and it cannot invalidate the good measurement.
const trOneHalfWritten = path.join(root, 'tr-one-half-written.jsonl');
fs.writeFileSync(trOneHalfWritten,
  JSON.stringify({ type: 'assistant', message: { usage: { input_tokens: 5, cache_creation_input_tokens: 10, cache_read_input_tokens: 1000 } } }) + '\n' +
  '{"type":"assistant","message":{"usa\n');
fireLoad(laneEvent('um2l-one-half-written', emptyDir, trOneHalfWritten));
assert('(b) POSITIVE CONTROL: ONE half-written line at the end does not invalidate the good measurement',
  ((readState(repo).sessions || {})['um2l-one-half-written'] || {}).context_tokens === TOK_EMPTY,
  `it is ${JSON.stringify(((readState(repo).sessions || {})['um2l-one-half-written'] || {}).context_tokens)}`);
// An ABSENT field IS a real 0: the API omits what there was none of.
const trNoCache = path.join(root, 'tr-no-cache.jsonl');
fs.writeFileSync(trNoCache, JSON.stringify({ type: 'assistant', message: { usage: { input_tokens: 7 } } }) + '\n');
fireLoad(laneEvent('sc3m-no-cache', emptyDir, trNoCache));
assert('(b) an ABSENT field DOES count as 0 (the API omits what there was none of)',
  ((readState(repo).sessions || {})['sc3m-no-cache'] || {}).context_tokens === 7);

// The `?` is demanded IN THE ROW of a specific session that could not be measured,
// not "there is a ? somewhere" (Codex, 09-15).
const rowOf = (out, id) => (out.split('\n').find((l) => l.includes(String(id).slice(0, 8))) || '');
const nRow = (out, id) => out.split('\n').findIndex((l) => l.includes(String(id).slice(0, 8)));
const earlyLoadAlerts = () => (readState(repo).counters.by_gate.terminal_load || 0);

// (c) THE PERCENTAGE (the owner, 09-15): the model window is 100 % and the ceiling is
// `autoCompactWindow` expressed over that million. There are not two percentages.
// The case they measured: 403,353 tokens -> 40 %, and it does NOT warn (the ceiling
// is 55 %).
const almostDir = path.join(repo, 'lane-almost');
fs.mkdirSync(almostDir, { recursive: true });
const trAlmost = path.join(root, 'tr-almost.jsonl');
fs.writeFileSync(trAlmost, JSON.stringify({ type: 'assistant', message: { usage: { input_tokens: TOK_ALMOST } } }) + '\n');
fireLoad(laneEvent('ca4o-almost-full', almostDir, trAlmost));
const board = loadCli(['load']);
assert('(c) the model window (1,000,000) is 100 %, and it says so',
  board.status === 0 && /1000000 tokens\) is 100 %/.test(board.stdout), board.stdout.slice(0, 200));
assert(`  ...and the load ceiling comes from autoCompactWindow: ${CEILING_TOKENS} -> ${PCT_CEILING} %`,
  new RegExp(`load ceiling is at ${PCT_CEILING} % \\(autoCompactWindow ${CEILING_TOKENS}\\)`).test(board.stdout),
  board.stdout.slice(0, 200));
assert('  ...403,353 tokens is 40 % of the million (what Claude Code shows), not 73 %',
  / 40%/.test(rowOf(board.stdout, 'ca4o-almost-full')) && !/73%/.test(board.stdout),
  rowOf(board.stdout, 'ca4o-almost-full'));
assert('  ...and 560,000 is 56 %', / 56%/.test(rowOf(board.stdout, 'le2b-lane-full')),
  rowOf(board.stdout, 'le2b-lane-full'));
const emptyConf = path.join(root, 'conf-no-window');
fs.mkdirSync(emptyConf, { recursive: true });
fs.writeFileSync(path.join(emptyConf, 'settings.json'), JSON.stringify({ model: 'x' }));
const noWindow = loadCli(['load'], { CLAUDE_CONFIG_DIR: emptyConf });
assert('  ...and with no `autoCompactWindow` the ceiling is shown as 100 %',
  /load ceiling is at 100 %/.test(noWindow.stdout) && /terminals with < 100 %:/.test(noWindow.stdout),
  noWindow.stdout.slice(0, 200));
// "The default 100 % is NO CEILING, not a 100 % ceiling": with no key it NEVER
// warns, not even with a session at exactly one million. And this is tested by
// really firing the gate and the Stop, not by looking at the board's text
// (Codex, 2nd round).
const millionDir = path.join(repo, 'lane-million');
fs.mkdirSync(millionDir, { recursive: true });
const trMillion = path.join(root, 'tr-million.jsonl');
fs.writeFileSync(trMillion, JSON.stringify({ type: 'assistant', message: { usage: { input_tokens: 1000000 } } }) + '\n');
fireLoad(laneEvent('ml5p-million-exact', millionDir, trMillion), HOOK, { CLAUDE_CONFIG_DIR: emptyConf });
const beforeNoCeiling = earlyLoadAlerts();
fireLoad({
  hook_event_name: 'PostToolUse', tool_name: 'Write', cwd: repo, session_id: 'du1a-owner-load',
  tool_input: { file_path: 'splits/BRIEF-NOCEILING.md', content: `# x\n- Folder: ${millionDir}\n` },
}, HOOK, { CLAUDE_CONFIG_DIR: emptyConf });
const stopNoCeiling = fireLoad({ hook_event_name: 'Stop', cwd: repo, session_id: 'du1a-owner-load' },
  HOOK, { CLAUDE_CONFIG_DIR: emptyConf });
assert('  ...and with no declared ceiling neither the gate nor the Stop warns, not even with 1,000,000 exactly',
  earlyLoadAlerts() === beforeNoCeiling && stopNoCeiling.code === 0 &&
  !/load ceiling/.test(stopNoCeiling.stdout),
  `alerts ${beforeNoCeiling}->${earlyLoadAlerts()} · stop: ${stopNoCeiling.stdout.slice(0, 200)}`);
// And a key that is NOT a number (`true`, `[550000]`) cannot turn into a ceiling of
// one token, which would leave ALL the terminals "full".
for (const [label, value] of [['true', true], ['[550000]', [550000]], ['"550000"', '550000']]) {
  const c = path.join(root, 'conf-junk-' + label.replace(/\W/g, ''));
  fs.mkdirSync(c, { recursive: true });
  fs.writeFileSync(path.join(c, 'settings.json'), JSON.stringify({ autoCompactWindow: value }));
  const r = loadCli(['load'], { CLAUDE_CONFIG_DIR: c });
  assert(`  ...and an autoCompactWindow that is not a number (${label}) does NOT turn into a 1-token ceiling`,
    r.status === 0 && /load ceiling is at 100 %/.test(r.stdout), r.stdout.slice(0, 160));
}

// (d) the board: real tokens, `?`, descending % order and the count
assert('(d) `load` prints the board with the transcript\'s real tokens',
  new RegExp(String(TOK_FULL)).test(board.stdout), board.stdout);
assert('  ...and a `?` in the row of every session that could not be measured',
  ['st4d-no-transcript', 'ci9i-unreadable-field', 'cf1k-unreliable-tail']
    .every((s) => / \?/.test(rowOf(board.stdout, s))), board.stdout);
assert('  ...and the full one\'s row carries its number, not a `?`',
  rowOf(board.stdout, 'le2b-lane-full').includes(String(TOK_FULL)), board.stdout);
// ROW POSITIONS are compared per session, not `indexOf('0%')`: that `0%` matched the
// suffix of `40%` and the check came out true even with the order reversed
// (Codex, 2nd round).
assert('  ...sorted by descending %: 56 % before 40 %, and 40 % before the ones at 0 %',
  nRow(board.stdout, 'le2b-lane-full') > 0 &&
  nRow(board.stdout, 'le2b-lane-full') < nRow(board.stdout, 'ca4o-almost-full') &&
  nRow(board.stdout, 'ca4o-almost-full') < nRow(board.stdout, 'va3c-lane-empty') &&
  nRow(board.stdout, 'va3c-lane-empty') < nRow(board.stdout, 'st4d-no-transcript'),
  board.stdout);
assert(`  ...with the count line "terminals with < ${PCT_CEILING} %: N"`,
  new RegExp(`terminals with < ${PCT_CEILING} %: \\d+`).test(board.stdout), board.stdout);
// free = owner + lane-empty + one-half-written + no-cache + almost-full (40 %).
// The 8 that could not be measured do NOT count, and neither does the 56 % one.
assert(`  ...and the UNMEASURED ones do not count as free (5 of 14 sessions)`,
  new RegExp(`terminals with < ${PCT_CEILING} %: 5\\b`).test(board.stdout), board.stdout);
// "it contains the board" is not enough: it is demanded that it be THE SAME text
// that `load` prints, otherwise the two could diverge without anybody finding out
// (Codex, 09-15). The two runs go BACK TO BACK on purpose (new sessions have been
// getting recorded in between, and comparing against an old board would be comparing
// two different photos). The "N min ago" column changes between the two, so it is
// normalized.
const boardNow = loadCli(['load']);
const state = loadCli(['status']);
const noClock = (s) => {
  const i = s.indexOf('LOAD BOARD');
  return i < 0 ? '' : s.slice(i).replace(/\d+ min ago/g, 'N min ago').trim();
};
assert('  ...and `status` carries INSIDE it the SAME board that `load` prints',
  state.status === 0 && boardNow.status === 0 &&
  noClock(boardNow.stdout).length > 0 && noClock(state.stdout) === noClock(boardNow.stdout),
  state.stdout.slice(-400));

// (e) the gate: it warns about the full one, it keeps quiet about the empty one
const loadBrief = (folder) => `# T9 — test brief\n\n## Where you work\n- Branch: main\n- Folder: ${folder}\n- Resources of yours: none\n`;
const loadDispatchEvent = (name, folder, session) => ({
  hook_event_name: 'PostToolUse', tool_name: 'Write', cwd: repo, session_id: session,
  tool_input: { file_path: `splits/${name}`, content: loadBrief(folder) },
});
const loadAlerts = () => (readState(repo).counters.by_gate.terminal_load || 0);
const beforeGate = loadAlerts();
const warning = fireLoad(loadDispatchEvent('BRIEF-T9.md', fullDir, 'du1a-owner-load'));
