// (g) mutants: every new check HAS to be able to fail
// The measurer ALSO returns whether the hooks ran fine. Without that, a mutant that
// simply BLOWS UP would give `alerts: 0` and would pass for "it stopped detecting"
// without having proved anything — the test would be decoration (Codex, 09-15). And
// "the session is not on the board" is told apart from "it is, but unmeasured".
const measureLoad = (bin) => {
  hardClearState(repo);
  const r1 = fireLoad({
    hook_event_name: 'PreToolUse', tool_name: 'Skill', cwd: repo, session_id: 'du1a-owner-load',
    tool_input: { skill: 'orq' },
  }, bin);
  const r2 = fireLoad(laneEvent('le2b-lane-full', fullDir,
    transcript('full2', { input_tokens: 32, cache_creation_input_tokens: 2770, cache_read_input_tokens: 557198 })), bin);
  const before = loadAlerts();
  const r3 = fireLoad(loadDispatchEvent('BRIEF-M.md', fullDir, 'du1a-owner-load'), bin);
  const S2 = readState(repo).sessions || {};
  const present = Object.prototype.hasOwnProperty.call(S2, 'le2b-lane-full');
  return {
    alerts: loadAlerts() - before,
    present,
    tokens: present ? S2['le2b-lane-full'].context_tokens : undefined,
    // the three hooks exited 0 and none of them spat an exception on stderr
    // Looking for one word is not enough: a TypeError is a blow-up too, and the
    // mutant would pass for "it stopped detecting" when in fact it broke
    // (Codex, 2nd round).
    ran: [r1, r2, r3].every((r) => r.code === 0 &&
      !/exception|Error|Cannot |is not a function|is not defined/i.test(r.stderr || '')),
  };
};
const baseLoad = measureLoad(HOOK);
assert('(g) POSITIVE CONTROL of the mutant: the healthy code runs, measures and warns',
  baseLoad.ran && baseLoad.present && baseLoad.tokens === TOK_FULL && baseLoad.alerts >= 1,
  JSON.stringify(baseLoad));

