const e2c11 = fire21({ hook_event_name: 'Stop', cwd: repo, session_id: 'du22-owner' });
assert('  ...and the owner hears ONE line per compaction, not one per lane',
  e2c11.code === 0 && handoffs() === handoffsBefore7a + 1, `handoffs ${handoffs()} (before ${handoffsBefore7a})`);

// 7b. A `session_id` THAT IS NOT A STRING. It identifies nobody: the hook exits 0,
// the header comes out all the same (that terminal has to know it compacted) and NO
// existing session is touched.
const before7b = JSON.stringify((readState(repo).sessions || {})[E2] || {});
const weirdSids = [null, 12345, ['74ce700b-e2-lane'], { id: 'x' }];
const outputs7b = weirdSids.map((sid) => fire21({ hook_event_name: 'SessionStart', source: 'compact',
  cwd: dirE2, session_id: sid, transcript_path: trE2Low }));
assert('(7b) a `session_id` that is not a string (null, number, array, object) does not blow the hook up: it exits 0',
  outputs7b.every((r) => r.code === 0 &&
    !/exception|Error|Cannot |is not a function|is not defined/i.test(r.stderr || '')),
  JSON.stringify(outputs7b.map((r) => r.code)));
assert('  ...and it still receives the compaction header (the terminal has to know)',
  outputs7b.every((r) => /^YOU JUST COMPACTED/.test(firstBlock(r))), firstBlock(outputs7b[2]).slice(0, 200));
assert('  ...and it does NOT touch the record of the session it resembles (neither its counter nor its handover)',
  JSON.stringify((readState(repo).sessions || {})[E2] || {}) === before7b,
  `before ${before7b.slice(0, 160)} / after ${JSON.stringify((readState(repo).sessions || {})[E2] || {}).slice(0, 160)}`);
// ...and a `source` that is not a string either CANNOT pass itself off as a compaction.
const e2c12 = fire21({ hook_event_name: 'SessionStart', source: ['compact'], cwd: dirE2,
  session_id: 'e2-source-array', transcript_path: trE2Low });
assert('  ...and an ARRAY `source` (["compact"]) does not count as a compaction',
  e2c12.code === 0 && !/YOU JUST COMPACTED/.test(e2c12.stdout), e2c12.stdout.slice(0, 200));

// 7c. AN ENORMOUS HANDOVER. It is trimmed by sections (T18: whole recomposable
// ones are dropped; here not even the protected ones fit and it is cut at the end),
// the path is named for the rest, and the trim ALSO has a cap: four chosen sections
// can weigh as much as the whole file.
hardClearState(repo);
skill21('du22-owner-big');
fire21({ hook_event_name: 'Stop', cwd: dirE2, session_id: 'e2-fat', transcript_path: trE2High });
const fatPath = ((readState(repo).sessions || {})['e2-fat'] || {}).handover_requested;
const filler = (t, kb) => `## ${t}\n` + (t + ' \u2014 \u00e1\u00e9\u00ed\u00f3\u00fa ' + 'x'.repeat(120) + '\n').repeat(kb * 8);
fs.writeFileSync(fatPath, [
  '# HANDOVER — the fat one', filler('1. MANDATE', 8), filler('3. LOCAL STATE', 40),
  filler('5. VERIFICATION', 8), filler('9. WARNINGS', 40), '',
].join('\n'), 'utf8');
fire21({ hook_event_name: 'PostToolUse', tool_name: 'Write', cwd: dirE2, session_id: 'e2-fat',
  tool_input: { file_path: fatPath, content: 'fat' } });
const e2c13 = fire21({ hook_event_name: 'SessionStart', source: 'compact', cwd: dirE2,
  session_id: 'e2-fat', transcript_path: trE2Low });
assert('(7c) an ENORMOUS handover is trimmed to its sections and says where the rest is',
  // T18 (22-09): the default cap goes from 12 to 16 KB and the trim respects sections.
  e2c13.code === 0 && /It weighs more than 16 KB/.test(contextOf(e2c13)) &&
  contextOf(e2c13).includes(fatPath) &&
  /## 1\. MANDATE/.test(contextOf(e2c13)) && !/## 9\. WARNINGS/.test(contextOf(e2c13)),
  contextOf(e2c13).slice(0, 300));
assert('  ...and the trim respects the cap in BYTES, not in characters (there are accents inside)',
  // T18: 16 KB of handover + the compaction header.
  Buffer.byteLength(contextOf(e2c13), 'utf8') < 17 * 1024 &&
  /trimmed: the rest is in the file/.test(contextOf(e2c13)),
  `${Buffer.byteLength(contextOf(e2c13), 'utf8')} bytes`);
// ...and an enormous one WITHOUT the template's headings sends the head of the file,
// also bounded: better a real piece than nothing.
fire21({ hook_event_name: 'Stop', cwd: dirE2, session_id: 'e2-no-titles', transcript_path: trE2High });
const noTitlesPath = ((readState(repo).sessions || {})['e2-no-titles'] || {}).handover_requested;
fs.writeFileSync(noTitlesPath, 'I wrote it my own way, with no headings\n' + ('filler \u00e1\n'.repeat(4000)), 'utf8');
fire21({ hook_event_name: 'PostToolUse', tool_name: 'Write', cwd: dirE2, session_id: 'e2-no-titles',
  tool_input: { file_path: noTitlesPath, content: 'x' } });
const e2c14 = fire21({ hook_event_name: 'SessionStart', source: 'compact', cwd: dirE2,
  session_id: 'e2-no-titles', transcript_path: trE2Low });
assert('  ...and an enormous one WITH NO headings sends the head of the file, bounded',
  e2c14.code === 0 && /I wrote it my own way/.test(contextOf(e2c14)) &&
  Buffer.byteLength(contextOf(e2c14), 'utf8') < 17 * 1024, `${Buffer.byteLength(contextOf(e2c14), 'utf8')} bytes`);   // T18: 16 KB cap

// 7d. THE FILE IS DELETED between being recorded and being injected. It is not "you
// did not write it" — that would be lying to it about its own work —: it is "I have
// not been able to read it", and the handover is still PENDING, it is not taken as
// read.
fire21({ hook_event_name: 'Stop', cwd: dirE2, session_id: 'e2-deleted', transcript_path: trE2High });
const deletedPath = ((readState(repo).sessions || {})['e2-deleted'] || {}).handover_requested;
fs.writeFileSync(deletedPath, '# HANDOVER — this one is going to be deleted\n\n## 1. MANDATE\nsomething\n', 'utf8');
fire21({ hook_event_name: 'PostToolUse', tool_name: 'Write', cwd: dirE2, session_id: 'e2-deleted',
  tool_input: { file_path: deletedPath, content: 'x' } });
fs.rmSync(deletedPath);
const e2c15 = fire21({ hook_event_name: 'SessionStart', source: 'compact', cwd: dirE2,
  session_id: 'e2-deleted', transcript_path: trE2Low });
assert('(7d) if the handover is no longer on disk, the hook does NOT accuse it of not having written it',
  e2c15.code === 0 && /I have NOT been able to read it now/.test(firstBlock(e2c15)) &&
  firstBlock(e2c15).includes(deletedPath) &&
  !/You did not write your handover/.test(firstBlock(e2c15)), firstBlock(e2c15).slice(0, 400));
assert('  ...and that handover is still PENDING (not read, not closed, not called out as read)',
  (() => {
    const L = readState(repo);
    const s = (L.sessions || {})['e2-deleted'] || {};
    const t = (L.handovers || []).find((x) => x && x.path === deletedPath) || {};
    const c = (L.compactions || []).find((x) => x && x.session === 'e2-deleted') || {};
    return s.handover_written === deletedPath && !t.closed_at && c.handover === null;
  })(), JSON.stringify((readState(repo).sessions || {})['e2-deleted'] || {}));

// 7e. `SessionStart(compact)` WITH NO `transcript_path`: there is no measurement, so
// the % is "?" — never an invented 0 —, but the handover is delivered just the same
// and the load warning is REARMED (compacting is, by definition, dropping).
fire21({ hook_event_name: 'Stop', cwd: dirE2, session_id: 'e2-unmeasured', transcript_path: trE2High });
const unmeasuredPath = ((readState(repo).sessions || {})['e2-unmeasured'] || {}).handover_requested;
fs.writeFileSync(unmeasuredPath, '# HANDOVER\n\n## 1. MANDATE\nI am still here with no measurement\n', 'utf8');
fire21({ hook_event_name: 'PostToolUse', tool_name: 'Write', cwd: dirE2, session_id: 'e2-unmeasured',
  tool_input: { file_path: unmeasuredPath, content: 'x' } });
assert('(7e) preparation: that session crossed the warning and was left marked',
  ((readState(repo).sessions || {})['e2-unmeasured'] || {}).warned_own === true);
const e2c16 = fire21({ hook_event_name: 'SessionStart', source: 'compact', cwd: dirE2,
  session_id: 'e2-unmeasured' });
assert('  ...a SessionStart(compact) with NO transcript says "? %" (never 0) and delivers the handover all the same',
  e2c16.code === 0 && /is now at \? % of the million/.test(firstBlock(e2c16)) &&
  /I am still here with no measurement/.test(contextOf(e2c16)), firstBlock(e2c16).slice(0, 300));
assert('  ...and it REARMS the load warning, even though there was no measurement to rearm it',
  ((readState(repo).sessions || {})['e2-unmeasured'] || {}).warned_own === false,
  JSON.stringify((readState(repo).sessions || {})['e2-unmeasured'] || {}));
const e2c17 = fire21({ hook_event_name: 'Stop', cwd: dirE2, session_id: 'e2-unmeasured', transcript_path: trE2High });
assert('  ...so the next crossing warns again (without this it stayed mute forever)',
  e2c17.code === 0 && RE_OWN.test(e2c17.stdout), e2c17.stdout.slice(0, 300));

// (8) MUTANTS. The two new pieces have to be able to fail.
const measureE2 = (bin) => {
  hardClearState(repo);
  const r0 = skill21('du22-mut');
  const r1 = fire21({ hook_event_name: 'Stop', cwd: dirE2, session_id: E2, transcript_path: trE2High }, bin);
  const rt = ((readState(repo).sessions || {})[E2] || {}).handover_requested;
  if (rt) fs.writeFileSync(rt, '# HANDOVER — E2\n\n## 1. MANDATE\nmy own real-case stuff\n', 'utf8');
  const r2 = fire21({ hook_event_name: 'PostToolUse', tool_name: 'Write', cwd: dirE2, session_id: E2,
    tool_input: { file_path: rt, content: 'x' } }, bin);
  const r3 = fire21({ hook_event_name: 'SessionStart', source: 'compact', cwd: dirE2,
    session_id: E2, transcript_path: trE2Low }, bin);
  const r4 = fire21({ hook_event_name: 'Stop', cwd: dirE2, session_id: E2, transcript_path: trE2Low }, bin);
  const r5 = fire21({ hook_event_name: 'Stop', cwd: dirE2, session_id: E2, transcript_path: trE2Low }, bin);
  return {
    warning: RE_OWN.test(r1.stdout),
    header: /YOU JUST COMPACTED/.test(contextOf(r3)),
    handover: /my own real-case stuff/.test(contextOf(r3)),
    shortLines: [r4, r5].filter((r) => /You just compacted \(/.test(r.stdout)).length,
    ran: [r0, r1, r2, r3, r4, r5].every((r) => (r.code === 0 || r.status === 0) &&
      !/exception|Error|Cannot |is not a function|is not defined/i.test(r.stderr || '')),
  };
};
const baseE2 = measureE2(HOOK);
assert('(8) POSITIVE CONTROL of the mutant: the healthy code warns, injects the handover and repeats the short line ONCE',
  baseE2.ran && baseE2.warning && baseE2.header && baseE2.handover && baseE2.shortLines === 1,
  JSON.stringify(baseE2));

const mC = path.join(root, 'm-c.js');
const injectionPatch = '  if (hBody) parts.push(hBody);';
assert('preparation of mutant m-c: the handover injection exists exactly like that in the source',
  source.includes(injectionPatch));
fs.writeFileSync(mC, source.replace(injectionPatch, '  /* mutated: no handover injection */'));
const mutC = measureE2(mC);
assert('the mutant WITHOUT the handover injection leaves the terminal with no memory (but it keeps warning)',
  mutC.ran && mutC.header === true && mutC.handover === false, JSON.stringify(mutC));

const mD = path.join(root, 'm-d.js');
const compactMarkPatch = '      mySession.compaction_warned = true;';
assert('preparation of mutant m-d: the `compaction_warned` mark exists exactly like that in the source',
  source.includes(compactMarkPatch));
fs.writeFileSync(mD, source.replace(compactMarkPatch, '      /* mutated: no mark */'));
const mutD = measureE2(mD);
assert('the mutant WITHOUT the `compaction_warned` mark repeats the short line at EVERY close',
  mutD.ran && mutD.shortLines === 2, JSON.stringify(mutD));

assert('THE OWNER\'S REAL SETTINGS.JSON DID NOT CHANGE AT ALL IN ANY TEST (the whole file)',
  realFingerprint() === realBefore, realDetail());

cli(['close'], repo);
try { fs.rmSync(dirE2, { recursive: true, force: true }); } catch { /* nothing */ }

/* ---------------- 23. (RETIRED IN T57) THE HOOK NO LONGER WRITES THE AIRBAG INTO settings.json */
// This section used to test the WRITING of autoCompactWindow (the owner, 15-09: "try
// adding it"): atomic, only that key, race with the reread, temporaries, fragile
// numbers, CRLF, nested or escaped key, {}. Since T57 (issue #8, the owner 17-09: "the
// skill WARNS, it does not write") that writing does not exist, and with it its 42
// assertions are retired. What replaces them lives in the T57 section at the end:
