/* ---------------- 24. THE BRAKE: the orchestrator does NOT edit code (point 11, the owner 09-15 21:30) */
// Until today `orchestrator_builds` only warned: 163 warnings measured in one
// workday, and the owner went on editing. With `brakes: {orchestrator_builds:
// "block"}` the PreToolUse returns `permissionDecision: "deny"`.
console.log('\n24. THE BRAKE — the orchestrator does not edit code without an ORDER from the owner');

const CONFIG_BLOCK = path.join(root, 'config-brake-block.json');
fs.writeFileSync(CONFIG_BLOCK, JSON.stringify({ warn_tokens: 500000, airbag_tokens: 550000, brakes: { orchestrator_builds: 'block' } }));
const CONFIG_WARN = path.join(root, 'config-brake-warn.json');
fs.writeFileSync(CONFIG_WARN, JSON.stringify({ warn_tokens: 500000, airbag_tokens: 550000, brakes: { orchestrator_builds: 'warn' } }));

const OWNER = 'owner-brake-session';
const setOwner = (sid) => {
  const lPath = path.join(repo, '.git', 'orchestrator-state.json');
  const Ld = JSON.parse(fs.readFileSync(lPath, 'utf8'));
  Ld.owner_session = sid;
  fs.writeFileSync(lPath, JSON.stringify(Ld));
};
const brakeEvent = (extra = {}) => ({
  hook_event_name: 'PreToolUse', tool_name: 'Edit', cwd: repo, session_id: OWNER,
  tool_input: { file_path: 'src/brake.js', old_string: 'x', new_string: 'a\nb\nc\nd' },
  ...extra,
});
const isDeny = (r) => {
  try { return JSON.parse(r.stdout).hookSpecificOutput.permissionDecision === 'deny'; } catch { return false; }
};

clearState(repo); setOwner(OWNER);
const blocked = fire(brakeEvent(), HOOK, { ORCH_CONFIG: CONFIG_BLOCK });
assert('(a) owner IN PERSON + Edit over code + brake "block" -> DENY',
  isDeny(blocked) && /The orchestrator does not edit code/.test(blocked.stdout), blocked.stdout.slice(0, 300));
assert('  ...and the text says what to do instead (dispatch it) and how to ask for permission',
  /dispatch it/.test(blocked.stdout) && /allow-edit --file <path> --order-from-owner/.test(blocked.stdout),
  blocked.stdout.slice(0, 400));
assert('  ...and the hook exits with 0 (the deny travels in the JSON, not in the exit code)', blocked.code === 0);

clearState(repo); setOwner(OWNER);
const warns = fire(brakeEvent(), HOOK, { ORCH_CONFIG: CONFIG_WARN });
assert('(b) POSITIVE CONTROL: with the brake at "warn" it only warns, it does NOT deny',
  !isDeny(warns) && /PRODUCT CODE/.test(warns.stdout), warns.stdout.slice(0, 200));
clearState(repo); setOwner(OWNER);
const noBrakes = fire(brakeEvent(), HOOK, { ORCH_CONFIG: TOY_CONFIG });
assert('  ...and without the `brakes` key the default value is "warn": it does not deny either',
  !isDeny(noBrakes) && /PRODUCT CODE/.test(noBrakes.stdout), noBrakes.stdout.slice(0, 200));

clearState(repo); setOwner(OWNER);
const otherLane = fire(brakeEvent({ session_id: 'lane-T7-session' }), HOOK, { ORCH_CONFIG: CONFIG_BLOCK });
assert('(c) NEGATIVE CONTROL: a LANE (another session) never receives a deny',
  !isDeny(otherLane) && otherLane.stdout === '', otherLane.stdout.slice(0, 200));

// MEASURED on 2026-09-16 with ORCH_CAPTURE: a SUBAGENT's events arrive with the
// MOTHER's session_id, but they carry `agent_id`. Without this distinction, putting
// the brake at "block" would have denied the work of ALL the lanes launched as
// subagents — the opposite of dispatching.
clearState(repo); setOwner(OWNER);
const herSubagent = fire(brakeEvent({ agent_id: 'a10032d95e834c09c', agent_type: 'general-purpose' }), HOOK, { ORCH_CONFIG: CONFIG_BLOCK });
assert('(d) a SUBAGENT of the owner (same session_id, with agent_id) does NOT receive a deny',
  !isDeny(herSubagent), herSubagent.stdout.slice(0, 200));
// CHANGED BY T3 (21-09): until today this line claimed "...but it still warns, which
// is what it used to do". That WAS the false positive: the warning said "The
// orchestrator is editing PRODUCT CODE" about something its subagent was editing.
// Now it does not accuse; it leaves a trace in `subagent_edit`.
assert('  ...and it NO LONGER accuses the orchestrator of what its subagent edits',
  !/PRODUCT CODE/.test(herSubagent.stdout), herSubagent.stdout.slice(0, 200));
assert('  ...but the trace IS left, with no counter and no accusation',
  (readState(repo).events || []).some((e) => e.type === 'subagent_edit') &&
  !(readState(repo).counters.by_gate.orchestrator_builds));

clearState(repo); setOwner(OWNER);
const docMd = fire(brakeEvent({ tool_input: { file_path: 'docs/plan.md', old_string: 'x', new_string: 'a\nb\nc\nd' } }), HOOK, { ORCH_CONFIG: CONFIG_BLOCK });
assert('(e) a .md never receives a deny (docs and briefs are not code)',
  !isDeny(docMd) && docMd.stdout === '', docMd.stdout.slice(0, 200));

// `allow-edit`: BOTH arguments, or there is no permission.
clearState(repo); setOwner(OWNER);
const noOrder = cli(['allow-edit', '--file', 'src/brake.js'], repo);
assert('(f) `allow-edit` with no --order-from-owner: rejects (exit 1)',
  noOrder.status === 1 && /BOTH arguments are mandatory/.test(noOrder.stdout), noOrder.stdout.slice(0, 200));
assert('  ...and with no --file either',
  cli(['allow-edit', '--order-from-owner', '21:40 do it yourself'], repo).status === 1);

const withPermission = cli(['allow-edit', '--file', path.join(repo, 'src', 'brake.js'),
  '--order-from-owner', '21:40 "do it yourself, the lane is not getting there"', '--lane', 'T7'], repo);
assert('(g) `allow-edit` with both arguments: it records it and says how long it lasts',
  withPermission.status === 0 && /30 minutes/.test(withPermission.stdout) &&
  (readState(repo).edit_permissions || []).length === 1, withPermission.stdout.slice(0, 300));
const withP = fire(brakeEvent(), HOOK, { ORCH_CONFIG: CONFIG_BLOCK });
assert('  ...and with the permission in force the Edit PASSES, and the warning QUOTES the owner\'s order',
  !isDeny(withP) && /WITH PERMISSION/.test(withP.stdout) && /do it yourself, the lane is not getting there/.test(withP.stdout) &&
  /lane T7 did not manage it/.test(withP.stdout), withP.stdout.slice(0, 400));

// EXPIRED permission: 31 minutes. It is aged in the ledger, not by waiting.
{
  const lPath = path.join(repo, '.git', 'orchestrator-state.json');
  const Ld = JSON.parse(fs.readFileSync(lPath, 'utf8'));
  Ld.edit_permissions[0].at = new Date(Date.now() - 31 * 60000).toISOString();
  fs.writeFileSync(lPath, JSON.stringify(Ld));
}
const expired = fire(brakeEvent(), HOOK, { ORCH_CONFIG: CONFIG_BLOCK });
assert('(h) EXPIRED permission (31 min): the deny comes back', isDeny(expired), expired.stdout.slice(0, 300));

// The permission is for THAT file, not a free pass.
clearState(repo); setOwner(OWNER);
cli(['allow-edit', '--file', path.join(repo, 'src', 'another-file.js'), '--order-from-owner', '21:41 that one'], repo);
const otherFile = fire(brakeEvent(), HOOK, { ORCH_CONFIG: CONFIG_BLOCK });
assert('(i) the permission holds ONLY for the file it names: another one is still denied',
  isDeny(otherFile) && /for OTHER files/.test(otherFile.stdout), otherFile.stdout.slice(0, 400));

// A change BY COMMAND is a change all the same.
clearState(repo); setOwner(OWNER);
const bySed = fire({
  hook_event_name: 'PreToolUse', tool_name: 'Bash', cwd: repo, session_id: OWNER,
  tool_input: { command: "sed -i 's/a/b/' src/brake.js" },
}, HOOK, { ORCH_CONFIG: CONFIG_BLOCK });
assert('(j) a `sed -i` over code of the repo falls into the SAME brake',
  isDeny(bySed), bySed.stdout.slice(0, 300));
assert('  ...and the ledger says it was by command, with the file',
  readState(repo).events.some((e) => e.type === 'edit_brake' && e.data && e.data.tool === 'Bash' &&
    /brake\.js$/.test(String(e.data.file))),
  JSON.stringify(readState(repo).events.filter((e) => e.type === 'edit_brake')));
const innocentBash = fire({
  hook_event_name: 'PreToolUse', tool_name: 'Bash', cwd: repo, session_id: OWNER,
  tool_input: { command: 'node tests/test-structure.mjs' },
}, HOOK, { ORCH_CONFIG: CONFIG_BLOCK });
assert('  ...NEGATIVE CONTROL: a Bash that only runs tests is not denied',
  !isDeny(innocentBash), innocentBash.stdout.slice(0, 200));

// `fable` as a subagent: the SAME permission lets it through.
clearState(repo); setOwner(OWNER);
const fableWithout = fire({
  hook_event_name: 'PreToolUse', tool_name: 'Agent', cwd: repo, session_id: OWNER,
  tool_input: { description: 'fat chunk', prompt: 'do it', model: 'fable' },
}, HOOK, { ORCH_CONFIG: CONFIG_BLOCK });
assert('(k) `fable` subagent WITHOUT permission: it warns', /`fable` subagent/.test(fableWithout.stdout), fableWithout.stdout.slice(0, 250));
cli(['allow-edit', '--file', path.join(repo, 'src', 'brake.js'), '--order-from-owner', '21:42 send one of your own height'], repo);
const fableWith = fire({
  hook_event_name: 'PreToolUse', tool_name: 'Agent', cwd: repo, session_id: OWNER,
  tool_input: { description: 'fat chunk 2', prompt: 'do it', model: 'fable' },
}, HOOK, { ORCH_CONFIG: CONFIG_BLOCK });
assert('  ...and with the permission in force it passes with no warning, and it is written down',
  !/`fable` subagent/.test(fableWith.stdout) &&
  readState(repo).events.some((e) => e.type === 'fable_allowed'), fableWith.stdout.slice(0, 250));

// MUTANT: without the role check, an EMPLOYEE receives the deny.
{
  const mRole = path.join(root, 'm-brake-role.js');
  // The role check lives in TWO places and both are needed: the early exit of
  // `checkBuilding` (the gate only looks at the owner) and `isOwnerInPerson` (and
  // besides, that it is them and not one of their agents). The mutant breaks both: if
  // with that an employee did NOT receive a deny, the check would be decoration.
  const PATCH_A = '  if (L.owner_session && session && session !== L.owner_session) return null;';
  const PATCH_B = '  if (!sid || sid !== L.owner_session) return false;';
  assert('preparation of the mutant: both role checks exist exactly like that in the source',
    source.includes(PATCH_A) && source.includes(PATCH_B));
  fs.writeFileSync(mRole, source.split(PATCH_A).join('  /* mutated: without looking at the role */')
    .replace(PATCH_B, '  if (!sid) return false;'));
  clearState(repo); setOwner(OWNER);
  const employee = fire(brakeEvent({ session_id: 'lane-session-T7' }), mRole, { ORCH_CONFIG: CONFIG_BLOCK });
  assert('MUTANT without the role check: an EMPLOYEE receives a deny (that is why it is needed)',
    isDeny(employee), employee.stdout.slice(0, 200));
}
// MUTANT: without the subagent distinction, the owner's lane-subagent freezes.
{
  const mSub = path.join(root, 'm-brake-subagent.js');
  // T3 (21-09): the distinction is no longer written by hand here with `agent_id`.
  // The three signals live in `subagentSignal`, and BOTH ask it: the cut
  // (`isOwnerInPerson`) and the warning (`checkBuilding`). That is why the mutant can
  // no longer remove just the line of the cut —the warning would come out first
  // through its own door and the deny would not be reached—: it blinds the signal AT
  // ITS SOURCE, which is exactly what shows that there is a single yardstick.
  const PATCH = "  if (str(e.agent_id)) return 'agent_id';";
  assert('preparation of the mutant: the distinction by `agent_id` exists exactly like that', source.includes(PATCH));
  fs.writeFileSync(mSub, source.replace(PATCH, '  /* mutated: without distinguishing subagents by agent_id */'));
  clearState(repo); setOwner(OWNER);
  const frozen = fire(brakeEvent({ agent_id: 'a1', agent_type: 'general-purpose' }), mSub, { ORCH_CONFIG: CONFIG_BLOCK });
  assert('MUTANT without the distinction by `agent_id`: the subagent-lane DOES receive a deny (it would freeze)',
    isDeny(frozen), frozen.stdout.slice(0, 200));
}

/* ---------------- 25. NAMED TERMINAL for BIG lanes (point 1) */
console.log('\n25. NAMED TERMINAL');
clearState(repo); setOwner(OWNER);

const unnamed = cli(['terminal', '--link', 'T9', '--session', 'session-T9'], repo);
