/* ---------------- 30. ORCH_CAPTURE: the diagnostic recorder (point 8) */
console.log('\n30. ORCH_CAPTURE');
clearState(repo);

const captureDir = path.join(root, 'captures');
fire({
  hook_event_name: 'PostToolUse', tool_name: 'Edit', cwd: repo, session_id: 'captured-session',
  agent_id: 'a123', tool_input: { file_path: 'src/x.js', old_string: 'a secret of the owner', new_string: 'another secret' },
  tool_response: { stdout: 'very long output with data' },
}, HOOK, { ORCH_CAPTURE: captureDir, ORCH_CONFIG: TOY_CONFIG });
const captured = fs.existsSync(captureDir) ? fs.readdirSync(captureDir) : [];
assert('(a) with `ORCH_CAPTURE` set, the payload is written down', captured.length === 1, captured.join(','));
const readCap = captured.length ? JSON.parse(fs.readFileSync(path.join(captureDir, captured[0]), 'utf8')) : {};
assert('  ...with the keys and the identifiers INTACT',
  readCap.session_id === 'captured-session' && readCap.agent_id === 'a123' &&
  readCap.tool_name === 'Edit' && readCap.hook_event_name === 'PostToolUse', JSON.stringify(readCap).slice(0, 300));
assert('  ...and the CONTENT replaced by its length, not copied',
  readCap.tool_input && readCap.tool_input.old_string === '<text:21>' &&
  !/a secret of the owner/.test(JSON.stringify(readCap)), JSON.stringify(readCap.tool_input));

// THE NEGATIVE IS RUN **WITH** THE VARIABLE, LOOKING AT ANOTHER FOLDER.
//
// Two earlier versions of this proved nothing: the first invented a folder that was
// never passed to the hook; the second ran again WITHOUT the variable, so the hook
// knew of no folder and not writing was the only thing it could do. An accidental
// capture SOMEWHERE ELSE passed both. (Codex gpt-5.6-sol, round 4.)
//
// What does prove it: a folder is TOLD to it (`toldDir`) and it is checked that it
// writes there and ONLY there — the other one (`untoldDir`) stays empty. And the
// mutant makes the hook ignore the variable and write into `untoldDir`: if the
// control were useless, that mutant would pass.
const capEvent = () => ({
  hook_event_name: 'PostToolUse', tool_name: 'Edit', cwd: repo, session_id: 'captured-session',
  tool_input: { file_path: 'src/x.js', old_string: 'a', new_string: 'b' },
});
const toldDir = path.join(root, 'captures-the-one-it-was-told');
const untoldDir = path.join(root, 'captures-nobody-told-it');
const howManyIn = (d) => { try { return fs.readdirSync(d).length; } catch { return 0; } };
fire(capEvent(), HOOK, { ORCH_CONFIG: TOY_CONFIG, ORCH_CAPTURE: toldDir });
assert('(b) WITH `ORCH_CAPTURE`, it writes into the folder it was told',
  howManyIn(toldDir) === 1, String(howManyIn(toldDir)));
assert('(b) ...and ONLY there: the other folder receives nothing',
  howManyIn(untoldDir) === 0, String(howManyIn(untoldDir)));
fire(capEvent(), HOOK, { ORCH_CONFIG: TOY_CONFIG });
assert('(b) and WITHOUT the variable it writes into neither of the two',
  howManyIn(toldDir) === 1 && howManyIn(untoldDir) === 0,
  `${howManyIn(toldDir)} / ${howManyIn(untoldDir)}`);
for (const f of fs.readdirSync(toldDir)) fs.rmSync(path.join(toldDir, f));

// MUTANT: a hook that IGNORES the variable and writes wherever it pleases has to
// fall into this control. It is told `toldDir` and the mutant writes into the other.
assert('preparation of the mutant: the `ORCH_CAPTURE` guard is where it is expected',
  source.includes("  const folder = String(process.env.ORCH_CAPTURE || '').trim();\n  if (!folder) return null;"));
const mCap = path.join(root, 'm30-capture.js');
fs.writeFileSync(mCap, source.replace(
  "  const folder = String(process.env.ORCH_CAPTURE || '').trim();\n  if (!folder) return null;",
  `  const folder = ${JSON.stringify(untoldDir)};`));
fire(capEvent(), mCap, { ORCH_CONFIG: TOY_CONFIG, ORCH_CAPTURE: toldDir });
assert('MUTANT: a hook that writes where nobody told it IS caught by this control',
  howManyIn(untoldDir) === 1 && howManyIn(toldDir) === 0,
  `${howManyIn(toldDir)} / ${howManyIn(untoldDir)}`);
for (const f of fs.readdirSync(untoldDir)) fs.rmSync(path.join(untoldDir, f));

// (c) THE REAL CAPTURES, ACTUALLY USED. `loadCapture` lives here, in the suite,
// which is what loads them; and the two stored captures are fed through the hook
// exactly as they arrived, so that they are not decoration.
const loadCapture = (p) => {
  try {
    const j = JSON.parse(fs.readFileSync(p, 'utf8'));
    return (j && typeof j === 'object' && !Array.isArray(j)) ? j : null;
  } catch { return null; }
};
const FIXTURES_DIR = path.join(path.dirname(path.dirname(HOOK)), 'tests', 'fixtures');
const capLoop = loadCapture(path.join(FIXTURES_DIR, 'capture-main-loop.json'));
assert('(c) `loadCapture` returns the real capture of the main loop',
  !!capLoop && capLoop.hook_event_name === 'PostToolUse' && capLoop.tool_name === 'Bash',
  JSON.stringify(capLoop).slice(0, 200));
const capSub = loadCapture(path.join(FIXTURES_DIR, 'capture-subagentstop.json'));
assert('  ...and the `SubagentStop` one, with its `agent_id` and its own transcript',
  !!capSub && typeof capSub.agent_id === 'string' && capSub.agent_id !== '' &&
  /subagents/.test(String(capSub.agent_transcript_path || '')), JSON.stringify(capSub).slice(0, 200));
assert('  ...and a file that is not JSON returns null, it does not blow up',
  loadCapture(path.join(FIXTURES_DIR, 'this-capture-does-not-exist.json')) === null);
{
  // The main-loop one, fed through the hook with THIS repo's cwd: it has to pass
  // without breaking anything and without denying (it is a read-only `Bash`).
  const rLoop = fire(Object.assign({}, capLoop, { cwd: repo }), HOOK, { ORCH_CONFIG: TOY_CONFIG });
  assert('  ...and the real main-loop capture goes through the hook without breaking it (exit 0, no deny)',
    rLoop.code === 0 && !/permissionDecision/.test(rLoop.stdout || ''), (rLoop.stdout || '').slice(0, 300));
}

