assert('(2) POSITIVE CONTROL: file ABSENT -> "You did not write your handover before compacting"',
  sc32absent.code === 0 && /You did not write your handover before compacting/.test(sc32absent.stdout),
  sc32absent.stdout.slice(0, 400));
assert('  ...with the advice to write it with a `cp`/`copy` from Bash',
  /write it with a `cp`\/`copy` from Bash/.test(sc32absent.stdout), sc32absent.stdout.slice(0, 500));

// (3) EMPTY file -> "I have NOT been able to read it" — it is NOT the same as "you
// did not write it": `recognizeHandoverOnDisk` DOES mark it `handover_written`
// (content === '' does not trigger `isOnlyTheTemplate`), but `handoverToInject`
// has nothing to inject.
clearState(repo);
heightT32('t32-empty');
const t32emptyPath = ((readState(repo).sessions || {})['t32-empty'] || {}).handover_requested;
fs.writeFileSync(t32emptyPath, '');
const sc32empty = fire21({ hook_event_name: 'SessionStart', source: 'compact', cwd: dir21, session_id: 't32-empty' });
assert('(3) EMPTY file -> it says it has NOT been able to read it (not "you did not write it")',
  sc32empty.code === 0 && /I have NOT been able to read it now/.test(sc32empty.stdout) &&
  !/You did not write your handover before compacting/.test(sc32empty.stdout),
  sc32empty.stdout.slice(0, 400));
assert('  ...and the ledger DOES mark it written (it is there, only illegible/empty)',
  ((readState(repo).sessions || {})['t32-empty'] || {}).handover_written === t32emptyPath);

// (4) THE TRAP: the file is ONLY the template the hook itself seeds when asking for
// the handover (nobody wrote a word over it) -> it counts as NOT written. Without
// `isOnlyTheTemplate`, "the file exists" proves nothing, because
// `handover_requested` ALWAYS points at a file that exists.
clearState(repo);
heightT32('t32-template');
const t32templatePath = ((readState(repo).sessions || {})['t32-template'] || {}).handover_requested;
assert('(4) preparation: the hook itself seeded the template (nobody wrote anything over it)',
  fs.existsSync(t32templatePath) && /## 1\. MANDATE/.test(fs.readFileSync(t32templatePath, 'utf8')),
  fs.existsSync(t32templatePath) ? fs.readFileSync(t32templatePath, 'utf8').slice(0, 120) : 'does not exist');
const sc32template = fire21({ hook_event_name: 'SessionStart', source: 'compact', cwd: dir21, session_id: 't32-template' });
assert('(4) THE TRAP: only the seeded template -> it counts as NOT written',
  sc32template.code === 0 && /You did not write your handover before compacting/.test(sc32template.stdout),
  sc32template.stdout.slice(0, 400));
assert('  ...and the ledger does NOT mark it `handover_written`',
  !((readState(repo).sessions || {})['t32-template'] || {}).handover_written);

// (5) MUTANT: without the call to `recognizeHandoverOnDisk`, case (1) (real
