const m32 = path.join(root, 'm32-handover.js');
fs.writeFileSync(m32, source.replace('recognizeHandoverOnDisk(L, sid, s);', '/* mutated: it recognizes nothing */ void 0;'));
clearState(repo);
fire21(stop21('t32-mutant', tr32), m32);
const t32mutantPath = ((readState(repo).sessions || {})['t32-mutant'] || {}).handover_requested;
