// (HIGH 2) A BLOCKED receipt, or one with NOT MET items, does NOT close the lane
// nor trigger the cleanup: `validate` checks format, not completion.
{
  const d36 = path.join(root, 'dispatches36');
  fs.mkdirSync(d36, { recursive: true });
  const brief36 = path.join(d36, 'BRIEF-T2-x.md');
  fs.writeFileSync(brief36, GOOD_BRIEF);
  const receipt = (state, result) => [
    '# RECEIPT — T2', '', '## STATE', state, '- Subagent calls: 2', '- Recommended next step: integrate', '',
    '## CLAIMED RESULT', result, '',
    '## FILES CHANGED', '```', ' src/x.js | 4 ++++', ' 1 file changed, 4 insertions(+)', 'M\tsrc/x.js', '```', '',
    '## INPUTS USED', '- nothing', '', '## CONSTRAINTS AND DEVIATIONS', '- none: met', '',
    '## ASSUMPTIONS AND OPEN QUESTIONS', '- none', '', '## ESCALATIONS', 'none', '',
  ].join('\n');
  const okRes = '- the thing works — proof: `node x.mjs` → 3 OK [V]\n- the other thing too — proof: `node y.mjs` → 2 OK [V]';
  const noRes = '- the thing works — proof: `node x.mjs` → 3 OK [V]\n- the other thing too — NOT MET: not enough time';

  const blockedPath = path.join(d36, 'RECEIPT-blocked.md');
  fs.writeFileSync(blockedPath, receipt('BLOCKED', okRes));
  const vBlocked = cli(['validate', '--lane', 'T2', '--receipt', blockedPath, '--brief', brief36], repo);
  assert('(HIGH 2) a BLOCKED receipt passes the format but does NOT close the lane',
    vBlocked.status === 0 && /I am not closing the lane or cleaning anything of its own/.test(vBlocked.stdout), vBlocked.stdout.slice(0, 500));
  const notMetPath = path.join(d36, 'RECEIPT-not-met.md');
  fs.writeFileSync(notMetPath, receipt('READY', noRes));
  const vNotMet = cli(['validate', '--lane', 'T2', '--receipt', notMetPath, '--brief', brief36], repo);
  assert('  ...and a READY with a "NOT MET" item does not either',
    vNotMet.status === 0 && /there are NOT MET items/.test(vNotMet.stdout), vNotMet.stdout.slice(0, 500));
  const readyPath = path.join(d36, 'RECEIPT-ready.md');
  fs.writeFileSync(readyPath, receipt('READY', okRes));
  const vReady = cli(['validate', '--lane', 'T2', '--receipt', readyPath, '--brief', brief36], repo);
  assert('  ...POSITIVE CONTROL: a READY with nothing unmet DOES close (it does not say it is not closing)',
    vReady.status === 0 && !/I am not closing the lane/.test(vReady.stdout), vReady.stdout.slice(0, 400));
}

// (HIGH 3) A handover a session has WRITTEN DOWN is not deleted, even if it is the
// oldest: the newest by `mtime` may be a freshly seeded template.
{
  clearState(repo); setOwner(OWNER);
  const dirT = path.join(repo, '.orchestrator', 'handovers');
  fs.mkdirSync(dirT, { recursive: true });
  const oldInUse = path.join(dirT, 'HANDOVER-c36inuse-20260101-0100.md');
  const newTemplate = path.join(dirT, 'HANDOVER-c36inuse-20260101-0200.md');
  fs.writeFileSync(oldInUse, '# the real one\n');
  fs.writeFileSync(newTemplate, '# the freshly seeded template\n');
  const h = (n) => new Date(Date.now() - n * 3600000);
  fs.utimesSync(oldInUse, h(5), h(5));
  fs.utimesSync(newTemplate, h(1), h(1));
  {
    const lPath = path.join(repo, '.git', 'orchestrator-state.json');
    const Ld = JSON.parse(fs.readFileSync(lPath, 'utf8'));
    Ld.owner_session = OWNER;
    Ld.sessions = Ld.sessions || {};
    Ld.sessions.c36inuse = { first_time: new Date().toISOString(), invocations: 1, handover_written: oldInUse };
    fs.writeFileSync(lPath, JSON.stringify(Ld));
  }
  cli(['close-lane', '--lane', 'c36inuse'], repo);
  assert('(HIGH 3) the handover the session has WRITTEN DOWN is not deleted, even if it is the oldest',
    fs.existsSync(oldInUse), JSON.stringify({ old: fs.existsSync(oldInUse), new: fs.existsSync(newTemplate) }));
}

