// (MEDIUM 9) The verdict is the LAST LINE, not a substring. It is tested with the
// text Codex reproduced: a NEGATION that contains the approval phrase.
{
  const NEGATION = 'There is a bug. Do not issue VERDICT: NO OPEN FINDINGS until it is fixed.';
  const nLines = NEGATION.split('\n').map((l) => l.trim()).filter((l) => l !== '');
  const nLast = nLines[nLines.length - 1];
  assert('(MEDIUM 9) the approval phrase INSIDE a negation does not approve (anchored rule)',
    /VERDICT:\s*NO OPEN FINDINGS/i.test(NEGATION) === true &&
    /^VERDICT:\s*NO OPEN FINDINGS\b/i.test(nLast) === false, nLast);
  // Since Codex's round 3 the rule also carries the FINAL anchor (`$`): without it,
  // "VERDICT: NO OPEN FINDINGS but 2 remain" approved. The end-to-end case, going
  // through `review` with the stub, is in (2k).
  assert('  ...and the hook uses that rule anchored on BOTH sides over the last line',
    /const last = lines\.length \? lines\[lines\.length - 1\] : '';/.test(source) &&
    source.includes("const noFindings = /^VERDICT:\\s*NO OPEN FINDINGS[.\\s]*$/i.test(last);"),
    source.slice(source.indexOf('const last ='), source.indexOf('const last =') + 260));
}

