  const v48e = cli(['validate', '--lane', 'T48', '--receipt', receiptInside48, '--brief', briefInside48], repo48);
  assert('(e) POSITIVE CONTROL: receipt AND brief live INSIDE the repo — they no longer accuse themselves of being rubbish',
    v48e.status === 0 && /^OK/.test(v48e.stdout), v48e.stdout.slice(0, 400));
