/* (6) the brake by command: BOTH false positives, and everything from before still green */
clearState(repo); setOwner(OWNER);
{
  const outsideTheRepo50 = fs.mkdtempSync(path.join(root, 't10-scratchpad-'));
  const cmdEvent50 = (command) => ({
    hook_event_name: 'PreToolUse', tool_name: 'Bash', cwd: repo, session_id: OWNER,
    tool_input: { command },
  });
  const denies50 = (command, bin = HOOK) => isDeny(fire(cmdEvent50(command), bin, { ORCH_CONFIG: CONFIG_BLOCK }));
  // (a) THE LITERAL CASE of 09-17 19:05: the only thing it writes is a `.md` in the
  // scratchpad; the deletion words are INSIDE the string it prints.
  const PRINTF_OF_THE_17TH =
    `printf '%s\\n' 'Pending: do not do rm -rf build or git clean -fd in the repo' >> ${outsideTheRepo50}/HANDOFF.md`;
  assert('(6a) the `printf` with deletion words INSIDE the string is NOT denied',
    !denies50(PRINTF_OF_THE_17TH));
  assert('  ...nor when the string names a code file of the repo',
    !denies50(`printf '%s\\n' 'tomorrow we have to touch scripts/h.js' >> ${outsideTheRepo50}/HANDOFF.md`));
  // (b) T9'S CASE (09-16): a temporary checker through a heredoc, at an ABSOLUTE
  // path outside the orchestrated repo.
  assert('(6b) the heredoc to an ABSOLUTE path outside the repo is NOT denied',
    !denies50(`cat > ${outsideTheRepo50}/t10-check.mjs <<'EOF'\nconsole.log('hello');\nEOF`));
  assert('  ...nor with `rm -rf` and `git restore .` INSIDE the heredoc\'s body',
    !denies50(`cat > ${outsideTheRepo50}/t10-check2.mjs <<'EOF'\nconsole.log('if it fails: rm -rf tmp and git restore .');\nEOF`));
  // EVERYTHING THAT ALREADY BRAKED STILL BRAKES. This is the half that matters: a
  // fix for false positives that opens a hole is not a fix.
  const stillBraking = [
    ['rm -rf build', 'rm -rf build'],
    ['sed -i over a file of the repo', 'sed -i s/a/b/ scripts/h.js'],
    ['sed -i with the target IN QUOTES', `sed -i 's/a/b/' "scripts/h.js"`],
    ['echo hello > scripts/h.js', 'echo hello > scripts/h.js'],
    ['git restore .', 'git restore .'],
    ['git apply fix.diff', 'git apply fix.diff'],
    ['rm src/a.js', 'rm src/a.js'],
    ['cp a.js src/', 'cp a.js src/'],
    ['heredoc to scripts/h.js', "cat > scripts/h.js <<'EOF'\nx\nEOF"],
    ['bash -c "rm -rf src" (there the deletion IS a command)', 'bash -c "rm -rf src"'],
  ];
  for (const [name, cmd] of stillBraking) {
    assert(`  POSITIVE CONTROL: \`${name}\` is STILL denied`, denies50(cmd));
  }
  const stillPassing = [
    ['node tests/test-x.mjs > output.txt', 'node tests/test-x.mjs > output.txt'],
    ['rm notes.md', 'rm notes.md'],
    ['cat > <outside>/payload.json <<EOF', `cat > ${outsideTheRepo50}/payload.json <<'EOF'\n{"a":1}\nEOF`],
    ['target with an unexpanded VARIABLE', 'cat > "$S/whatever.js" <<\'EOF\'\nx\nEOF'],
  ];
  for (const [name, cmd] of stillPassing) {
    assert(`  NEGATIVE CONTROL: \`${name}\` still passes`, !denies50(cmd));
  }
  // MUTANT: looking at the RAW command (without emptying the text that is only
  // written), the `printf` of 09-17 is denied again.
  const PATCH_6 = '  const cleaned = withoutTextThatIsOnlyWritten(text);';
  assert('  preparation of the mutant (6): the emptying of the text exists exactly like that', source.includes(PATCH_6));
  const m6 = path.join(root, 'm-t10-brake.js');
  fs.writeFileSync(m6, source.replace(PATCH_6, '  const cleaned = text;'));
  assert('  MUTANT (6) looking at the raw command: the `printf` of 09-17 is DENIED again',
    denies50(PRINTF_OF_THE_17TH, m6));
}

/* (8) the Buffer `slice` (deprecated) swapped for `subarray` */
