    writeA(v2);
    const p9f = path.join(root, 'p-t8-9f.txt');
    cliT8(['review', '--lane', lane, '--model', 'gpt-6-astra'],
      { STUB_PROMPT_TO: p9f, STUB_VERDICT: TWO_FINDINGS });
    const row9f = rowT8(lane);
    const onDisk = row9f && row9f.bounded_diff_file ? read(row9f.bounded_diff_file) : '';
    const inPrompt = (/<<<BOUNDED DIFF>>>\n([\s\S]*?)\n<<<END OF THE BOUNDED DIFF>>>/.exec(read(p9f)) || [])[1] || '';
    assert('(T8-9f) the saved `-bounded.diff` is EXACTLY the trimming that was sent to Codex',
      !!row9f && typeof row9f.bounded_diff_file === 'string' && onDisk.length > 0 && onDisk === inPrompt,
      `disk=${onDisk.length} prompt=${inPrompt.length}`);
