  git(['checkout', '--', 'a.txt'], repoT8);

  // ---- (T8-10) THE THREE THAT THE ORCHESTRATOR HAD FIXED FROM ROUND 3 ----

  // (10g) A REVERTED HEADER also prevents the targeted one. A mode change brings no
  // `@@`: it lives in the header. If the broad one saw it and the fix undid
  // it, that fix is in no diff and cannot be shown.
  {
    const lane = 'T8hdrrev';
    const exec = path.join(repoT8, 'script-t8.sh');
    fs.writeFileSync(exec, '#!/bin/sh\necho hello\n');
    git(['add', '-A'], repoT8);
    git(['commit', '-qm', 'script for the mode change'], repoT8);
    // The change the BROAD one sees: in the SAME file, mode 755 (it lives in the
    // header, without any `@@`) **and** a content change (a hunk). The hunk
    // matters: that way the file still appears in the next round's diff
    // and the only thing that disappears is the HEADER unit — which is
    // precisely the case being tested, and not "the whole file went away".
    git(['update-index', '--chmod=+x', 'script-t8.sh'], repoT8);
    fs.writeFileSync(exec, '#!/bin/sh\necho goodbye\n');
    writeA(v1);
    const dBroad = git(['diff', 'HEAD'], repoT8);
    assert('(T8-10g) preparation: the mode change comes out as a HEADER, without any `@@` of its own',
      /^old mode /m.test(dBroad || '') && /^new mode /m.test(dBroad || '') &&
      /^\+echo goodbye$/m.test(dBroad || ''), (dBroad || '').slice(0, 400));
    cliT8(['review', '--lane', lane, '--model', 'gpt-6-astra'], { STUB_VERDICT: TWO_FINDINGS });
    // The "fix": the mode is UNDONE (the header disappears) but the content
    // hunk is still there, changed. The file does NOT leave the diff.
    git(['update-index', '--chmod=-x', 'script-t8.sh'], repoT8);
    fs.writeFileSync(exec, '#!/bin/sh\necho see you later\n');
    writeA(v2);
    const r10g = cliT8(['review', '--lane', lane, '--model', 'gpt-6-astra'], { STUB_VERDICT: TWO_FINDINGS });
    const row10g = rowT8(lane);
    assert('  ...and when it is reverted, the round is NOT born targeted: it is born BROAD',
      !/narrowed to the diff of the fixes/.test(r10g.stdout || '') && !!row10g && row10g.bounded === false,
      (r10g.stdout || '').slice(0, 300));
    // CLEANUP: first `a.txt` goes back to HEAD —if not, the `git add -A` below
    // would swallow it in the commit and the next tests would start from
    // another base—, then the script is deleted and its removal is committed. `git rm --cached`
    // does NOT work: the index carries a mode different from the tree's and from HEAD's,
    // and git refuses without `-f` (measured: it blew up the whole suite).
    git(['checkout', '--', 'a.txt'], repoT8);
    try { fs.rmSync(exec); } catch { /* never mind */ }
    git(['add', '-A'], repoT8);
    git(['commit', '-qm', 'out goes the script'], repoT8);
  }
