    const bnd = (/<<<BOUNDED DIFF>>>\n([\s\S]*?)\n<<<END OF THE BOUNDED DIFF>>>/.exec(read(pM)) || [])[1] || '';
    assert('MUTANT (o): without counting the reverted headers, the round is born targeted and the undone mode does NOT go inside',
      /narrowed to the diff of the fixes/.test(rM.stdout || '') && !/old mode /.test(bnd),
      (rM.stdout || '').slice(0, 200) + ' || bounded=' + bnd.slice(0, 200));
    git(['checkout', '--', 'a.txt'], repoT8);
    try { fs.rmSync(exec); } catch { /* never mind */ }
